     1→/**
     2→ * FreeLang crypto Module: 암호화
     3→ * 30개 함수 (해시, 대칭, 비대칭 암호화)
     4→ */
     5→
     6→const crypto = require('crypto');
     7→
     8→// ============================================================================
     9→// Hash 함수 (6개)
    10→// ============================================================================
    11→
    12→/**
    13→ * MD5 해시 생성
    14→ * @param {string} data - 데이터
    15→ * @returns {string} 16진수 해시
    16→ */
    17→function md5(data) {
    18→  return crypto.createHash('md5').update(String(data)).digest('hex');
    19→}
    20→
    21→/**
    22→ * SHA1 해시 생성
    23→ * @param {string} data - 데이터
    24→ * @returns {string} 16진수 해시
    25→ */
    26→function sha1(data) {
    27→  return crypto.createHash('sha1').update(String(data)).digest('hex');
    28→}
    29→
    30→/**
    31→ * SHA256 해시 생성
    32→ * @param {string} data - 데이터
    33→ * @returns {string} 16진수 해시
    34→ */
    35→function sha256(data) {
    36→  return crypto.createHash('sha256').update(String(data)).digest('hex');
    37→}
    38→
    39→/**
    40→ * SHA512 해시 생성
    41→ * @param {string} data - 데이터
    42→ * @returns {string} 16진수 해시
    43→ */
    44→function sha512(data) {
    45→  return crypto.createHash('sha512').update(String(data)).digest('hex');
    46→}
    47→
    48→/**
    49→ * SHA384 해시 생성
    50→ * @param {string} data - 데이터
    51→ * @returns {string} 16진수 해시
    52→ */
    53→function sha384(data) {
    54→  return crypto.createHash('sha384').update(String(data)).digest('hex');
    55→}
    56→
    57→/**
    58→ * HMAC-SHA256 생성
    59→ * @param {string} data - 데이터
    60→ * @param {string} key - 시크릿 키
    61→ * @returns {string} 16진수 해시
    62→ */
    63→function hmacSha256(data, key) {
    64→  return crypto.createHmac('sha256', key).update(String(data)).digest('hex');
    65→}
    66→
    67→// ============================================================================
    68→// 대칭 암호화 (8개)
    69→// ============================================================================
    70→
    71→/**
    72→ * AES-256-CBC 암호화
    73→ * @param {string} plaintext - 평문
    74→ * @param {string} key - 256비트 키 (32바이트)
    75→ * @param {string} iv - 초기화 벡터 (16바이트)
    76→ * @returns {string} 16진수 암호문
    77→ */
    78→function aesEncrypt(plaintext, key, iv) {
    79→  const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from(key), Buffer.from(iv));
    80→  let encrypted = cipher.update(plaintext);
    81→  encrypted = Buffer.concat([encrypted, cipher.final()]);
    82→  return encrypted.toString('hex');
    83→}
    84→
    85→/**
    86→ * AES-256-CBC 복호화
    87→ * @param {string} ciphertext - 암호문 (16진수)
    88→ * @param {string} key - 256비트 키
    89→ * @param {string} iv - 초기화 벡터
    90→ * @returns {string} 평문
    91→ */
    92→function aesDecrypt(ciphertext, key, iv) {
    93→  const decipher = crypto.createDecipheriv('aes-256-cbc', Buffer.from(key), Buffer.from(iv));
    94→  let decrypted = decipher.update(Buffer.from(ciphertext, 'hex'));
    95→  decrypted = Buffer.concat([decrypted, decipher.final()]);
    96→  return decrypted.toString();
    97→}
    98→
    99→/**
   100→ * AES-128-CBC 암호화
   101→ * @param {string} plaintext - 평문
   102→ * @param {string} key - 128비트 키 (16바이트)
   103→ * @param {string} iv - 초기화 벡터
   104→ * @returns {string} 16진수 암호문
   105→ */
   106→function aes128Encrypt(plaintext, key, iv) {
   107→  const cipher = crypto.createCipheriv('aes-128-cbc', Buffer.from(key), Buffer.from(iv));
   108→  let encrypted = cipher.update(plaintext);
   109→  encrypted = Buffer.concat([encrypted, cipher.final()]);
   110→  return encrypted.toString('hex');
   111→}
   112→
   113→/**
   114→ * AES-128-CBC 복호화
   115→ * @param {string} ciphertext - 암호문 (16진수)
   116→ * @param {string} key - 128비트 키
   117→ * @param {string} iv - 초기화 벡터
   118→ * @returns {string} 평문
   119→ */
   120→function aes128Decrypt(ciphertext, key, iv) {
   121→  const decipher = crypto.createDecipheriv('aes-128-cbc', Buffer.from(key), Buffer.from(iv));
   122→  let decrypted = decipher.update(Buffer.from(ciphertext, 'hex'));
   123→  decrypted = Buffer.concat([decrypted, decipher.final()]);
   124→  return decrypted.toString();
   125→}
   126→
   127→/**
   128→ * DES 암호화
   129→ * @param {string} plaintext - 평문
   130→ * @param {string} key - DES 키 (8바이트)
   131→ * @param {string} iv - 초기화 벡터
   132→ * @returns {string} 16진수 암호문
   133→ */
   134→function desEncrypt(plaintext, key, iv) {
   135→  const cipher = crypto.createCipheriv('des-cbc', Buffer.from(key), Buffer.from(iv));
   136→  let encrypted = cipher.update(plaintext);
   137→  encrypted = Buffer.concat([encrypted, cipher.final()]);
   138→  return encrypted.toString('hex');
   139→}
   140→
   141→/**
   142→ * DES 복호화
   143→ * @param {string} ciphertext - 암호문 (16진수)
   144→ * @param {string} key - DES 키
   145→ * @param {string} iv - 초기화 벡터
   146→ * @returns {string} 평문
   147→ */
   148→function desDecrypt(ciphertext, key, iv) {
   149→  const decipher = crypto.createDecipheriv('des-cbc', Buffer.from(key), Buffer.from(iv));
   150→  let decrypted = decipher.update(Buffer.from(ciphertext, 'hex'));
   151→  decrypted = Buffer.concat([decrypted, decipher.final()]);
   152→  return decrypted.toString();
   153→}
   154→
   155→// ============================================================================
   156→// 인코딩/디코딩 (8개)
   157→// ============================================================================
   158→
   159→/**
   160→ * Base64 인코딩
   161→ * @param {string} data - 데이터
   162→ * @returns {string} Base64 문자열
   163→ */
   164→function base64Encode(data) {
   165→  return Buffer.from(String(data)).toString('base64');
   166→}
   167→
   168→/**
   169→ * Base64 디코딩
   170→ * @param {string} encoded - Base64 문자열
   171→ * @returns {string} 디코딩된 데이터
   172→ */
   173→function base64Decode(encoded) {
   174→  return Buffer.from(encoded, 'base64').toString();
   175→}
   176→
   177→/**
   178→ * Hex 인코딩
   179→ * @param {string} data - 데이터
   180→ * @returns {string} 16진수 문자열
   181→ */
   182→function hexEncode(data) {
   183→  return Buffer.from(String(data)).toString('hex');
   184→}
   185→
   186→/**
   187→ * Hex 디코딩
   188→ * @param {string} encoded - 16진수 문자열
   189→ * @returns {string} 디코딩된 데이터
   190→ */
   191→function hexDecode(encoded) {
   192→  return Buffer.from(encoded, 'hex').toString();
   193→}
   194→
   195→/**
   196→ * UTF-8 인코딩
   197→ * @param {string} data - 데이터
   198→ * @returns {string} UTF-8 바이트 배열 (16진수)
   199→ */
   200→function utf8Encode(data) {
   201→  return Buffer.from(String(data), 'utf8').toString('hex');
   202→}
   203→
   204→/**
   205→ * UTF-8 디코딩
   206→ * @param {string} encoded - 16진수 UTF-8 바이트
   207→ * @returns {string} 텍스트
   208→ */
   209→function utf8Decode(encoded) {
   210→  return Buffer.from(encoded, 'hex').toString('utf8');
   211→}
   212→
   213→/**
   214→ * URL 인코딩
   215→ * @param {string} data - 데이터
   216→ * @returns {string} URL 인코딩된 문자열
   217→ */
   218→function urlEncode(data) {
   219→  return encodeURIComponent(String(data));
   220→}
   221→
   222→/**
   223→ * URL 디코딩
   224→ * @param {string} encoded - URL 인코딩된 문자열
   225→ * @returns {string} 디코딩된 데이터
   226→ */
   227→function urlDecode(encoded) {
   228→  return decodeURIComponent(encoded);
   229→}
   230→
   231→// ============================================================================
   232→// 난수 생성 (6개)
   233→// ============================================================================
   234→
   235→/**
   236→ * 암호학적으로 안전한 난수 생성 (정수)
   237→ * @param {number} max - 최댓값
   238→ * @returns {number}
   239→ */
   240→function randomInt(max) {
   241→  return crypto.randomInt(0, max);
   242→}
   243→
   244→/**
   245→ * 암호학적으로 안전한 난수 생성 (16진수 문자열)
   246→ * @param {number} bytes - 바이트 수 (기본: 16)
   247→ * @returns {string} 16진수 문자열
   248→ */
   249→function randomHex(bytes = 16) {
   250→  return crypto.randomBytes(bytes).toString('hex');
   251→}
   252→
   253→/**
   254→ * 암호학적으로 안전한 난수 생성 (Base64 문자열)
   255→ * @param {number} bytes - 바이트 수
   256→ * @returns {string} Base64 문자열
   257→ */
   258→function randomBase64(bytes = 16) {
   259→  return crypto.randomBytes(bytes).toString('base64');
   260→}
   261→
   262→/**
   263→ * 난수 바이트 생성
   264→ * @param {number} size - 바이트 크기
   265→ * @returns {string} 16진수 문자열
   266→ */
   267→function randomBytes(size) {
   268→  return crypto.randomBytes(size).toString('hex');
   269→}
   270→
   271→/**
   272→ * UUID v4 생성
   273→ * @returns {string} UUID
   274→ */
   275→function uuidv4() {
   276→  return crypto.randomUUID();
   277→}
   278→
   279→/**
   280→ * 암호학적으로 안전한 문자열 생성
   281→ * @param {number} length - 길이
   282→ * @returns {string} 무작위 문자열
   283→ */
   284→function randomString(length = 32) {
   285→  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
   286→  let result = '';
   287→  const bytes = crypto.randomBytes(length);
   288→  for (let i = 0; i < length; i++) {
   289→    result += chars[bytes[i] % chars.length];
   290→  }
   291→  return result;
   292→}
   293→
   294→// ============================================================================
   295→// 키 생성 (2개)
   296→// ============================================================================
   297→
   298→/**
   299→ * AES-256 키 생성
   300→ * @returns {string} 32바이트 16진수 문자열
   301→ */
   302→function generateAes256Key() {
   303→  return crypto.randomBytes(32).toString('hex');
   304→}
   305→
   306→/**
   307→ * IV (초기화 벡터) 생성
   308→ * @returns {string} 16바이트 16진수 문자열
   309→ */
   310→function generateIv() {
   311→  return crypto.randomBytes(16).toString('hex');
   312→}
   313→
   314→// ============================================================================
   315→// Module Exports
   316→// ============================================================================
   317→
   318→module.exports = {
   319→  // Hash (6개)
   320→  md5,
   321→  sha1,
   322→  sha256,
   323→  sha512,
   324→  sha384,
   325→  hmacSha256,
   326→
   327→  // 대칭 암호화 (8개)
   328→  aesEncrypt,
   329→  aesDecrypt,
   330→  aes128Encrypt,
   331→  aes128Decrypt,
   332→  desEncrypt,
   333→  desDecrypt,
   334→
   335→  // 인코딩/디코딩 (8개)
   336→  base64Encode,
   337→  base64Decode,
   338→  hexEncode,
   339→  hexDecode,
   340→  utf8Encode,
   341→  utf8Decode,
   342→  urlEncode,
   343→  urlDecode,
   344→
   345→  // 난수 생성 (6개)
   346→  randomInt,
   347→  randomHex,
   348→  randomBase64,
   349→  randomBytes,
   350→  uuidv4,
   351→  randomString,
   352→
   353→  // 키 생성 (2개)
   354→  generateAes256Key,
   355→  generateIv
   356→};
