     1→/**
     2→ * FreeLang encoding Module: 인코딩/디코딩
     3→ * 25개 함수 (Base64, Hex, URL, UTF-8, 데이터 변환)
     4→ */
     5→
     6→const crypto = require('crypto');
     7→
     8→// ============================================================================
     9→// Base64 (4개 함수)
    10→// ============================================================================
    11→
    12→/**
    13→ * Base64 인코딩
    14→ * @param {string} data - 데이터
    15→ * @returns {string} Base64 문자열
    16→ */
    17→function base64Encode(data) {
    18→  return Buffer.from(String(data)).toString('base64');
    19→}
    20→
    21→/**
    22→ * Base64 디코딩
    23→ * @param {string} encoded - Base64 문자열
    24→ * @returns {string} 디코딩된 데이터
    25→ */
    26→function base64Decode(encoded) {
    27→  try {
    28→    return Buffer.from(encoded, 'base64').toString();
    29→  } catch (e) {
    30→    throw new Error('Invalid Base64 string');
    31→  }
    32→}
    33→
    34→/**
    35→ * Base64 유효성 확인
    36→ * @param {string} encoded - Base64 문자열
    37→ * @returns {boolean}
    38→ */
    39→function isBase64(encoded) {
    40→  try {
    41→    return Buffer.from(encoded, 'base64').toString('base64') === encoded;
    42→  } catch (e) {
    43→    return false;
    44→  }
    45→}
    46→
    47→/**
    48→ * Base64url (URL-safe) 인코딩
    49→ * @param {string} data - 데이터
    50→ * @returns {string}
    51→ */
    52→function base64urlEncode(data) {
    53→  return Buffer.from(String(data)).toString('base64')
    54→    .replace(/\+/g, '-')
    55→    .replace(/\//g, '_')
    56→    .replace(/=/g, '');
    57→}
    58→
    59→// ============================================================================
    60→// Hex (4개 함수)
    61→// ============================================================================
    62→
    63→/**
    64→ * Hex 인코딩
    65→ * @param {string} data - 데이터
    66→ * @returns {string} 16진수 문자열
    67→ */
    68→function hexEncode(data) {
    69→  return Buffer.from(String(data)).toString('hex');
    70→}
    71→
    72→/**
    73→ * Hex 디코딩
    74→ * @param {string} encoded - 16진수 문자열
    75→ * @returns {string} 디코딩된 데이터
    76→ */
    77→function hexDecode(encoded) {
    78→  try {
    79→    return Buffer.from(encoded, 'hex').toString();
    80→  } catch (e) {
    81→    throw new Error('Invalid hex string');
    82→  }
    83→}
    84→
    85→/**
    86→ * Hex 유효성 확인
    87→ * @param {string} encoded - 16진수 문자열
    88→ * @returns {boolean}
    89→ */
    90→function isHex(encoded) {
    91→  return /^[0-9a-fA-F]*$/.test(encoded) && encoded.length % 2 === 0;
    92→}
    93→
    94→/**
    95→ * Hex 버퍼로 변환
    96→ * @param {string} hexString - 16진수 문자열
    97→ * @returns {Buffer}
    98→ */
    99→function hexToBuffer(hexString) {
   100→  return Buffer.from(hexString, 'hex');
   101→}
   102→
   103→// ============================================================================
   104→// URL 인코딩 (4개 함수)
   105→// ============================================================================
   106→
   107→/**
   108→ * URL 인코딩
   109→ * @param {string} data - 데이터
   110→ * @returns {string} URL 인코딩된 문자열
   111→ */
   112→function urlEncode(data) {
   113→  return encodeURIComponent(String(data));
   114→}
   115→
   116→/**
   117→ * URL 디코딩
   118→ * @param {string} encoded - URL 인코딩된 문자열
   119→ * @returns {string} 디코딩된 데이터
   120→ */
   121→function urlDecode(encoded) {
   122→  try {
   123→    return decodeURIComponent(encoded);
   124→  } catch (e) {
   125→    throw new Error('Invalid URL encoding');
   126→  }
   127→}
   128→
   129→/**
   130→ * URL 컴포넌트 인코딩 (슬래시 포함)
   131→ * @param {string} data - 데이터
   132→ * @returns {string}
   133→ */
   134→function urlPathEncode(data) {
   135→  return String(data).split('/').map(part => encodeURIComponent(part)).join('/');
   136→}
   137→
   138→/**
   139→ * Query String 인코딩
   140→ * @param {object} obj - 객체
   141→ * @returns {string}
   142→ */
   143→function queryStringEncode(obj) {
   144→  const parts = [];
   145→  for (const [key, value] of Object.entries(obj)) {
   146→    parts.push(`${encodeURIComponent(key)}=${encodeURIComponent(String(value))}`);
   147→  }
   148→  return parts.join('&');
   149→}
   150→
   151→// ============================================================================
   152→// UTF-8 / ASCII (4개 함수)
   153→// ============================================================================
   154→
   155→/**
   156→ * 문자열을 UTF-8 바이트로 변환
   157→ * @param {string} data - 데이터
   158→ * @returns {string} 16진수 문자열
   159→ */
   160→function utf8Encode(data) {
   161→  return Buffer.from(String(data), 'utf8').toString('hex');
   162→}
   163→
   164→/**
   165→ * UTF-8 바이트에서 문자열로 변환
   166→ * @param {string} hex - 16진수 문자열
   167→ * @returns {string}
   168→ */
   169→function utf8Decode(hex) {
   170→  return Buffer.from(hex, 'hex').toString('utf8');
   171→}
   172→
   173→/**
   174→ * ASCII 인코딩
   175→ * @param {string} data - 데이터
   176→ * @returns {string} 16진수 문자열
   177→ */
   178→function asciiEncode(data) {
   179→  return Buffer.from(String(data), 'ascii').toString('hex');
   180→}
   181→
   182→/**
   183→ * ASCII 디코딩
   184→ * @param {string} hex - 16진수 문자열
   185→ * @returns {string}
   186→ */
   187→function asciiDecode(hex) {
   188→  return Buffer.from(hex, 'hex').toString('ascii');
   189→}
   190→
   191→// ============================================================================
   192→// 데이터 변환 (5개 함수)
   193→// ============================================================================
   194→
   195→/**
   196→ * 버퍼를 문자열로 변환
   197→ * @param {Buffer} buffer - 버퍼
   198→ * @param {string} encoding - 인코딩 (utf8, hex, base64 등)
   199→ * @returns {string}
   200→ */
   201→function bufferToString(buffer, encoding = 'utf8') {
   202→  if (Buffer.isBuffer(buffer)) {
   203→    return buffer.toString(encoding);
   204→  }
   205→  return String(buffer);
   206→}
   207→
   208→/**
   209→ * 문자열을 버퍼로 변환
   210→ * @param {string} data - 데이터
   211→ * @param {string} encoding - 인코딩
   212→ * @returns {Buffer}
   213→ */
   214→function stringToBuffer(data, encoding = 'utf8') {
   215→  return Buffer.from(String(data), encoding);
   216→}
   217→
   218→/**
   219→ * 배열을 버퍼로 변환
   220→ * @param {number[]} arr - 바이트 배열
   221→ * @returns {Buffer}
   222→ */
   223→function arrayToBuffer(arr) {
   224→  return Buffer.from(Array.isArray(arr) ? arr : []);
   225→}
   226→
   227→/**
   228→ * 버퍼를 배열로 변환
   229→ * @param {Buffer} buffer - 버퍼
   230→ * @returns {number[]}
   231→ */
   232→function bufferToArray(buffer) {
   233→  if (Buffer.isBuffer(buffer)) {
   234→    return Array.from(buffer);
   235→  }
   236→  return [];
   237→}
   238→
   239→/**
   240→ * 인코딩 변환
   241→ * @param {string} data - 데이터
   242→ * @param {string} fromEncoding - 원본 인코딩
   243→ * @param {string} toEncoding - 대상 인코딩
   244→ * @returns {string}
   245→ */
   246→function convert(data, fromEncoding, toEncoding) {
   247→  try {
   248→    const buffer = Buffer.from(data, fromEncoding);
   249→    return buffer.toString(toEncoding);
   250→  } catch (e) {
   251→    throw new Error(`Conversion error: ${e.message}`);
   252→  }
   253→}
