   257→// ============================================================================
   258→
   259→/**
   260→ * 데이터 크기 (바이트)
   261→ * @param {string} data - 데이터
   262→ * @returns {number}
   263→ */
   264→function byteLength(data) {
   265→  return Buffer.byteLength(String(data), 'utf8');
   266→}
