   268→/**
   269→ * Base32 인코딩
   270→ * @param {string} data - 데이터
   271→ * @returns {string}
   272→ */
   273→function base32Encode(data) {
   274→  const base32Chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
   275→  let bits = '';
   276→  const bytes = Buffer.from(String(data));
   277→
   278→  for (let i = 0; i < bytes.length; i++) {
   279→    bits += bytes[i].toString(2).padStart(8, '0');
   280→  }
   281→
   282→  bits = bits.padEnd(Math.ceil(bits.length / 5) * 5, '0');
   283→
   284→  let result = '';
   285→  for (let i = 0; i < bits.length; i += 5) {
   286→    const chunk = bits.substring(i, i + 5);
   287→    result += base32Chars[parseInt(chunk, 2)];
   288→  }
   289→
   290→  return result;
   291→}
