   293→/**
   294→ * Base32 디코딩
   295→ * @param {string} encoded - Base32 문자열
   296→ * @returns {string}
   297→ */
   298→function base32Decode(encoded) {
   299→  const base32Chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
   300→  let bits = '';
   301→
   302→  for (const char of encoded) {
   303→    const index = base32Chars.indexOf(char.toUpperCase());
   304→    if (index < 0) throw new Error('Invalid Base32 character');
   305→    bits += index.toString(2).padStart(5, '0');
   306→  }
   307→
   308→  let result = '';
   309→  bits = bits.slice(0, Math.floor(bits.length / 8) * 8);
   310→  for (let i = 0; i < bits.length; i += 8) {
   311→    const byte = parseInt(bits.substring(i, i + 8), 2);
   312→    result += String.fromCharCode(byte);
   313→  }
   314→
   315→  return result;
   316→}
