   318→/**
   319→ * HTML 이스케이프
   320→ * @param {string} data - 데이터
   321→ * @returns {string}
   322→ */
   323→function htmlEscape(data) {
   324→  const map = {
   325→    '&': '&amp;',
   326→    '<': '&lt;',
   327→    '>': '&gt;',
   328→    '"': '&quot;',
   329→    "'": '&#39;'
   330→  };
   331→  return String(data).replace(/[&<>"']/g, (char) => map[char]);
