   342→    '&lt;': '<',
   343→    '&gt;': '>',
   344→    '&quot;': '"',
   345→    '&#39;': "'"
   346→  };
   347→  return String(data).replace(/&amp;|&lt;|&gt;|&quot;|&#39;/g, (match) => map[match]);
   348→}
