    93→function deepMerge(obj1, obj2) {
    94→  const result = { ...obj1 };
    95→  for (const key of Object.keys(obj2)) {
    96→    if (typeof obj2[key] === 'object' && obj2[key] !== null && typeof result[key] === 'object' && result[key] !== null) {
    97→      result[key] = deepMerge(result[key], obj2[key]);
    98→    } else {
    99→      result[key] = obj2[key];
   100→    }
   101→  }
   102→  return result;
   103→}
   104→
   105→/**
   106→ * 특정 경로 값 추출 (경로: "a.b.c")
   107→ * @param {object} obj - 객체
   108→ * @param {string} path - 경로
   109→ * @param {any} defaultValue - 기본값
   110→ * @returns {any}
   111→ */
   112→function get(obj, path, defaultValue = null) {
   113→  const keys = path.split('.');
   114→  let current = obj;
   115→  for (const key of keys) {
   116→    if (current && typeof current === 'object' && key in current) {
   117→      current = current[key];
   118→    } else {
   119→      return defaultValue;
   120→    }
   121→  }
   122→  return current;
   123→}
   124→
   125→/**
   126→ * 특정 경로에 값 설정
   127→ * @param {object} obj - 객체
   128→ * @param {string} path - 경로
   129→ * @param {any} value - 설정할 값
   130→ * @returns {object} 수정된 객체
   131→ */
   132→function set(obj, path, value) {
   133→  const keys = path.split('.');
   134→  let current = obj;
   135→  for (let i = 0; i < keys.length - 1; i++) {
   136→    const key = keys[i];
   137→    if (!(key in current) || typeof current[key] !== 'object') {
   138→      current[key] = {};
   139→    }
   140→    current = current[key];
   141→  }
   142→  current[keys[keys.length - 1]] = value;
   143→  return obj;
   144→}
   145→
   146→/**
   147→ * 특정 경로 값 제거
   148→ * @param {object} obj - 객체
   149→ * @param {string} path - 경로
   150→ * @returns {object}
   151→ */
   152→function unset(obj, path) {
   153→  const keys = path.split('.');
   154→  let current = obj;
   155→  for (let i = 0; i < keys.length - 1; i++) {
   156→    if (!(keys[i] in current)) return obj;
   157→    current = current[keys[i]];
   158→  }
   159→  delete current[keys[keys.length - 1]];
   160→  return obj;
   161→}
   162→
   163→// ============================================================================
   164→// 검증 (3개 함수)
   165→// ============================================================================
   166→
   167→/**
   168→ * JSON 스키마 검증 (간단한 타입 체크)
   169→ * @param {any} obj - 검증할 객체
   170→ * @param {object} schema - 스키마 {key: type, ...}
   171→ * @returns {boolean}
   172→ */
   173→function validate(obj, schema) {
   174→  if (typeof obj !== 'object' || obj === null) return false;
   175→  for (const [key, expectedType] of Object.entries(schema)) {
   176→    if (!(key in obj)) return false;
   177→    const actualType = typeof obj[key];
   178→    if (actualType !== expectedType && expectedType !== 'any') return false;
   179→  }
   180→  return true;
   181→}
   182→
   183→/**
   184→ * 필수 필드 확인
   185→ * @param {object} obj - 객체
   186→ * @param {string[]} requiredFields - 필수 필드 배열
   187→ * @returns {boolean}
   188→ */
   189→function hasRequiredFields(obj, requiredFields) {
   190→  for (const field of requiredFields) {
   191→    if (!(field in obj) || obj[field] === null || obj[field] === undefined) {
   192→      return false;
   193→    }
   194→  }
   195→  return true;
   196→}
   197→
   198→/**
   199→ * 필드 타입 확인
   200→ * @param {object} obj - 객체
   201→ * @param {string} field - 필드명
   202→ * @param {string} expectedType - 예상 타입
   203→ * @returns {boolean}
   204→ */
   205→function isType(obj, field, expectedType) {
   206→  if (!(field in obj)) return false;
   207→  return typeof obj[field] === expectedType;
   208→}
   209→
   210→// ============================================================================
   211→// 유틸리티 (2개 함수)
   212→// ============================================================================
   213→
   214→/**
   215→ * 키 정렬 (오름차순)
   216→ * @param {any} obj - 객체
   217→ * @returns {any}
   218→ */
   219→function sortKeys(obj) {
   220→  if (typeof obj !== 'object' || obj === null || Array.isArray(obj)) {
   221→    return obj;
   222→  }
   223→  const sorted = {};
   224→  const keys = Object.keys(obj).sort();
   225→  for (const key of keys) {
   226→    sorted[key] = sortKeys(obj[key]);
   227→  }
   228→  return sorted;
   229→}
   230→
   231→/**
   232→ * 비어있는 필드 제거
   233→ * @param {object} obj - 객체
   234→ * @returns {object}
   235→ */
   236→function compact(obj) {
   237→  if (typeof obj !== 'object' || obj === null) {
   238→    return obj;
   239→  }
   240→  if (Array.isArray(obj)) {
   241→    return obj.map(item => compact(item)).filter(item => item !== null && item !== undefined);
   242→  }
   243→  const result = {};
   244→  for (const [key, value] of Object.entries(obj)) {
   245→    if (value !== null && value !== undefined && value !== '') {
   246→      result[key] = compact(value);
   247→    }
   248→  }
   249→  return result;
   250→}
   251→
   252→// ============================================================================
   253→// Module Exports
   254→// ============================================================================
   255→
   256→module.exports = {
   257→  // 기본 (4개)
   258→  parse,
   259→  stringify,
   260→  isValid,
   261→  normalize,
   262→
   263→  // 조작 (6개)
   264→  clone,
   265→  merge,
   266→  deepMerge,
   267→  get,
   268→  set,
   269→  unset,
   270→
   271→  // 검증 (3개)
   272→  validate,
   273→  hasRequiredFields,
   274→  isType,
   275→
   276→  // 유틸리티 (2개)
   277→  sortKeys,
   278→  compact
   279→};
