   100→/**
   101→ * CPU 사용률 추정 (간단한 방식)
   102→ * @returns {number} 0-100 범위의 백분율 (추정치)
   103→ */
   104→function getCpuUsage() {
   105→  const cpus = os.cpus();
   106→  let totalIdle = 0;
   107→  let totalTick = 0;
   108→
   109→  cpus.forEach((cpu) => {
   110→    for (const type of Object.keys(cpu.times)) {
   111→      totalTick += cpu.times[type];
   112→    }
   113→    totalIdle += cpu.times.idle;
   114→  });
   115→
   116→  const idle = totalIdle / cpus.length;
   117→  const total = totalTick / cpus.length;
   118→  const usage = 100 - ~~(100 * idle / total);
   119→
   120→  return Math.max(0, Math.min(100, usage));
   121→}
   122→
   123→/**
   124→ * CPU 코어별 정보
   125→ * @returns {object[]}
