   207→    const urlObj = new url.URL(urlStr);
   208→    const protocol = urlObj.protocol === 'https:' ? https : http;
   209→    const requestOptions = {
   210→      hostname: urlObj.hostname,
   211→      port: urlObj.port,
   212→      path: urlObj.pathname + urlObj.search,
   213→      method: 'HEAD',
   214→      ...options
   215→    };
   216→
   217→    protocol.request(requestOptions, (res) => {
   218→      resolve({
   219→        status: res.statusCode,
   220→        headers: res.headers,
   221→        body: ''
   222→      });
   223→    }).on('error', reject).end();
