   233→function options(urlStr, opts = {}) {
   234→  return new Promise((resolve, reject) => {
   235→    const urlObj = new url.URL(urlStr);
   236→    const protocol = urlObj.protocol === 'https:' ? https : http;
   237→    const requestOptions = {
   238→      hostname: urlObj.hostname,
