   240→      path: urlObj.pathname + urlObj.search,
   241→      method: 'OPTIONS',
   242→      ...opts
   243→    };
   244→
   245→    protocol.request(requestOptions, (res) => {
   246→      let data = '';
   247→      res.on('data', (chunk) => { data += chunk; });
   248→      res.on('end', () => {
   249→        resolve({
   250→          status: res.statusCode,
   251→          headers: res.headers,
