   259→/**
   260→ * 일반 요청 전송
   261→ * @param {string} urlStr - URL
   262→ * @param {object} options - {method, body, headers, ...}
   263→ * @returns {Promise<object>}
   264→ */
   265→function request(urlStr, options = {}) {
   266→  return new Promise((resolve, reject) => {
   267→    const urlObj = new url.URL(urlStr);
   268→    const protocol = urlObj.protocol === 'https:' ? https : http;
   269→    const method = options.method || 'GET';
   270→    const bodyStr = options.body ? (typeof options.body === 'string' ? options.body : JSON.stringify(options.body)) : '';
   271→
   272→    const requestOptions = {
   273→      hostname: urlObj.hostname,
   274→      port: urlObj.port,
   275→      path: urlObj.pathname + urlObj.search,
   276→      method: method,
   277→      headers: options.headers || {},
   278→      ...options
   279→    };
   280→
   281→    if (bodyStr) {
   282→      requestOptions.headers['Content-Length'] = Buffer.byteLength(bodyStr);
   283→    }
   284→
   285→    const req = protocol.request(requestOptions, (res) => {
   286→      let data = '';
   287→      res.on('data', (chunk) => { data += chunk; });
   288→      res.on('end', () => {
   289→        resolve({
   290→          status: res.statusCode,
   291→          headers: res.headers,
   292→          body: data
   293→        });
   294→      });
   295→    }).on('error', reject);
   296→
   297→    if (bodyStr) req.write(bodyStr);
   298→    req.end();
   299→  });
   300→}
