   565→/**
   566→ * 간단한 라우터 생성
   567→ * @returns {object} 라우터 객체
   568→ */
   569→function createRouter() {
   570→  const routes = {};
   571→
   572→  return {
   573→    get: (path, handler) => {
   574→      routes[`GET:${path}`] = handler;
   575→    },
   576→    post: (path, handler) => {
   577→      routes[`POST:${path}`] = handler;
   578→    },
   579→    put: (path, handler) => {
   580→      routes[`PUT:${path}`] = handler;
   581→    },
   582→    delete: (path, handler) => {
   583→      routes[`DELETE:${path}`] = handler;
   584→    },
   585→    patch: (path, handler) => {
   586→      routes[`PATCH:${path}`] = handler;
   587→    },
   588→    all: (path, handler) => {
   589→      for (const method of ['GET', 'POST', 'PUT', 'DELETE', 'PATCH']) {
   590→        routes[`${method}:${path}`] = handler;
   591→      }
   592→    },
   593→    handle: (req, res) => {
   594→      const key = `${req.method}:${req.url}`;
   595→      const handler = routes[key];
   596→      if (handler) {
   597→        handler(req, res);
   598→      } else {
   599→        res.statusCode = 404;
   600→        res.end('Not Found');
   601→      }
   602→    },
   603→    routes: () => Object.keys(routes)
   604→  };
   605→}
