   617→/**
   618→ * 경로 매칭 (와일드카드)
   619→ * @param {string} pattern - 패턴 (예: /api/:id)
   620→ * @param {string} path - 경로
   621→ * @returns {object|null} {id: "123", ...} 또는 null
   622→ */
   623→function matchPathParams(pattern, path) {
   624→  const patternParts = pattern.split('/').filter(p => p);
   625→  const pathParts = path.split('/').filter(p => p);
   626→
   627→  if (patternParts.length !== pathParts.length) return null;
   628→
   629→  const params = {};
   630→  for (let i = 0; i < patternParts.length; i++) {
   631→    const part = patternParts[i];
   632→    if (part.startsWith(':')) {
   633→      params[part.substring(1)] = pathParts[i];
   634→    } else if (part !== pathParts[i]) {
   635→      return null;
   636→    }
   637→  }
   638→
   639→  return params;
   640→}
