    10→/**
    11→ * SELECT 쿼리 빌더
    12→ * @param {string[]} columns - 컬럼 목록
    13→ * @param {string} table - 테이블명
    14→ * @returns {object} 쿼리 빌더 객체
    15→ */
    16→function select(columns, table) {
    17→  let query = `SELECT ${columns.join(', ')} FROM ${table}`;
    18→  let conditions = [];
    19→  let joins = [];
    20→  let orderBy = null;
    21→  let limit_ = null;
    22→
    23→  return {
    24→    where: (condition) => {
    25→      conditions.push(condition);
    26→      return arguments.callee.builder;
    27→    },
    28→    join: (joinClause) => {
    29→      joins.push(joinClause);
    30→      return arguments.callee.builder;
    31→    },
    32→    order: (column, direction = 'ASC') => {
    33→      orderBy = `${column} ${direction}`;
    34→      return arguments.callee.builder;
    35→    },
    36→    limit: (count) => {
    37→      limit_ = count;
    38→      return arguments.callee.builder;
    39→    },
    40→    build: () => {
    41→      let sql = query;
    42→      if (joins.length > 0) sql += ' ' + joins.join(' ');
    43→      if (conditions.length > 0) sql += ' WHERE ' + conditions.join(' AND ');
    44→      if (orderBy) sql += ' ORDER BY ' + orderBy;
    45→      if (limit_) sql += ' LIMIT ' + limit_;
    46→      return sql;
    47→    },
    48→    builder: this
    49→  };
    50→}
