    52→/**
    53→ * INSERT 쿼리 빌더
    54→ * @param {string} table - 테이블명
    55→ * @param {object} values - {column: value, ...}
    56→ * @returns {string} INSERT 쿼리
    57→ */
    58→function insert(table, values) {
    59→  const columns = Object.keys(values);
    60→  const vals = columns.map(col => escapeValue(values[col]));
