   230→ * @param {string} column - 컬럼명
   231→ * @param {any} start - 시작값
   232→ * @param {any} end - 종료값
   233→ * @returns {string}
   234→ */
   235→function buildBetween(column, start, end) {
   236→  return `${column} BETWEEN ${escapeValue(start)} AND ${escapeValue(end)}`;
   237→}
   238→
   239→/**
   240→ * LIKE 절 생성
   241→ * @param {string} column - 컬럼명
   242→ * @param {string} pattern - 패턴
   243→ * @returns {string}
   244→ */
   245→function buildLike(column, pattern) {
   246→  return `${column} LIKE '${escapeLike(String(pattern))}'`;
   247→}
   248→
   249→/**
   250→ * 배열을 INSERT 문으로 변환
   251→ * @param {string} table - 테이블명
   252→ * @param {object[]} rows - 행 배열
   253→ * @returns {string}
   254→ */
   255→function bulkInsert(table, rows) {
   256→  if (!rows || rows.length === 0) return '';
   257→
   258→  const columns = Object.keys(rows[0]);
   259→  const valuesList = rows.map(row => {
   260→    const vals = columns.map(col => escapeValue(row[col]));
   261→    return `(${vals.join(', ')})`;
   262→  });
   263→
   264→  return `INSERT INTO ${table} (${columns.join(', ')}) VALUES ${valuesList.join(', ')}`;
   265→}
